func collectCompositeMembership(rows *orm.Rows, keyFn func(*CompositeMembershipRow) orm.Key) *orm.Collection[CompositeMembershipRow] {
	c := orm.NewCollection[CompositeMembershipRow](len(rows.Data))
	for _, vals := range rows.Data {
		r := scanCompositeMembership(vals, rows.Assemble, rows)
		if keyFn != nil {
			c.Put(keyFn(r), r)
			continue
		}
		key, ok := orm.KeyFromRow(vals, rows.Assemble.Key)
		if !ok {
			panic("assembly collection key contains null")
		}
		c.Put(key, r)
	}
	return c
}

func collectCompositeMembershipDirect(rows []*CompositeMembershipRow, keyFn func(*CompositeMembershipRow) orm.Key) *orm.Collection[CompositeMembershipRow] {
	c := orm.NewCollection[CompositeMembershipRow](len(rows))
	for _, r := range rows {
		if keyFn != nil {
			c.Put(keyFn(r), r)
		} else {
			c.Put(orm.KeyFromValues([]any{r.TenantId, r.AccountId}), r)
		}
	}
	return c
}

